#!/usr/bin/env python3
"""
Techfest IIT Bombay Website Downloader
Downloads the complete landing page with all assets
"""
import os
import requests
import time
from pathlib import Path
from urllib.parse import urljoin

BASE_URL = 'https://techfest.org/'
OUTPUT_DIR = 'techfest_website'

headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
    'Referer': 'https://techfest.org/',
}

def download_file(url, output_path):
    """Download a file and save it to the specified path"""
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, 'wb') as f:
            f.write(response.content)
        print(f"  OK: {output_path}")
        return True
    except Exception as e:
        print(f"  FAIL: {url} -> {e}")
        return False

# Create directories
dirs = [
    f'{OUTPUT_DIR}/static/css',
    f'{OUTPUT_DIR}/static/js',
    f'{OUTPUT_DIR}/static/media',
]
for d in dirs:
    os.makedirs(d, exist_ok=True)

print("=== Downloading CSS ===")
download_file(
    'https://techfest.org/static/css/main.bc778095.css',
    f'{OUTPUT_DIR}/static/css/main.bc778095.css'
)

